UPDATE video_import_item
SET status = 'SUCCEEDED', video_id = #{videoId}, fail_reason = NULL, finish_time = #{finishTime}
WHERE id = #{id} AND status = 'RUNNING'

UPDATE video_import_item
SET status = 'FAILED', fail_reason = #{failReason}, finish_time = #{finishTime}
WHERE id = #{id} AND status = 'RUNNING'
